from collections import deque

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    background_color = grid[0][0]
    visited = [[False] * cols for _ in range(rows)]
    queue = deque()
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Add edge cells that are background color
    for r in [0, rows - 1]:
        for c in range(cols):
            if grid[r][c] == background_color and not visited[r][c]:
                visited[r][c] = True
                queue.append((r, c))

    for c in range(cols):
        if grid[0][c] == background_color and not visited[0][c]:
            visited[0][c] = True
            queue.append((0, c))
        if grid[rows - 1][c] == background_color and not visited[rows - 1][c]:
            visited[rows - 1][c] = True
            queue.append((rows - 1, c))

    for r in range(rows):
        if grid[r][0] == background_color and not visited[r][0]:
            visited[r][0] = True
            queue.append((r, 0))
        if grid[r][cols - 1] == background_color and not visited[r][cols - 1]:
            visited[r][cols - 1] = True
            queue.append((r, cols - 1))

    # BFS
    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == background_color and not visited[nr][nc]:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Transform enclosed cells to 4
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == background_color and not visited[r][c]:
                grid[r][c] = 4
    return grid
